public class LoanApplicant {
    private final String name;
    private final int creditScore;
    private final double monthlyIncome;
    private final double monthlyDebt;

    public LoanApplicant(String name, int creditScore, double monthlyIncome, double monthlyDebt) {
        this.name = name;
        this.creditScore = creditScore;
        this.monthlyIncome = monthlyIncome;
        this.monthlyDebt = monthlyDebt;
    }

    public String getName() { return name; }
    public int getCreditScore() { return creditScore; }
    public double getMonthlyIncome() { return monthlyIncome; }
    public double getMonthlyDebt() { return monthlyDebt; }
}

class LoanDecision {
    private final boolean approved;
    private final String reason;

    public LoanDecision(boolean approved, String reason) {
        this.approved = approved;
        this.reason = reason;
    }

    public boolean isApproved() { return approved; }
    public String getReason() { return reason; }
}

class LoanApprovalService {
    // the actual business rules, expressed as plain constants inside the service itself
    private static final int MIN_CREDIT_SCORE = 650;
    private static final double MAX_DEBT_TO_INCOME = 0.40;

    // the one entry point into this layer, a plain object in, a plain object out
    public LoanDecision evaluate(LoanApplicant applicant) {
        if (applicant.getCreditScore() < MIN_CREDIT_SCORE) {
            return new LoanDecision(false, "credit score " + applicant.getCreditScore() + " is below the minimum of " + MIN_CREDIT_SCORE);
        }

        // derived data computed fresh here, never trusted as a precomputed value from outside
        double debtToIncome = applicant.getMonthlyDebt() / applicant.getMonthlyIncome();
        if (debtToIncome > MAX_DEBT_TO_INCOME) {
            return new LoanDecision(false, "debt to income ratio " + debtToIncome + " exceeds the maximum of " + MAX_DEBT_TO_INCOME);
        }

        return new LoanDecision(true, "meets the minimum credit score and debt to income requirements");
    }
}

public class Main {
    public static void main(String[] args) {
        // no controller, no HTTP request, no database connection anywhere in this file
        LoanApprovalService service = new LoanApprovalService();

        LoanApplicant alice = new LoanApplicant("Alice", 720, 8000.0, 2000.0);
        LoanApplicant bob = new LoanApplicant("Bob", 580, 5000.0, 1000.0);

        LoanDecision aliceDecision = service.evaluate(alice);
        System.out.println(alice.getName() + ": approved = " + aliceDecision.isApproved() + ", reason = " + aliceDecision.getReason());

        LoanDecision bobDecision = service.evaluate(bob);
        System.out.println(bob.getName() + ": approved = " + bobDecision.isApproved() + ", reason = " + bobDecision.getReason());
    }
}

