class LoanApplicant:
    def __init__(self, name, credit_score, monthly_income, monthly_debt):
        self.name = name
        self.credit_score = credit_score
        self.monthly_income = monthly_income
        self.monthly_debt = monthly_debt


class LoanDecision:
    def __init__(self, approved, reason):
        self.approved = approved
        self.reason = reason


class LoanApprovalService:
    # the actual business rules, expressed as plain constants inside the service itself
    MIN_CREDIT_SCORE = 650
    MAX_DEBT_TO_INCOME = 0.40

    # the one entry point into this layer, a plain object in, a plain object out
    def evaluate(self, applicant):
        if applicant.credit_score < self.MIN_CREDIT_SCORE:
            return LoanDecision(False, f"credit score {applicant.credit_score} is below the minimum of {self.MIN_CREDIT_SCORE}")

        # derived data computed fresh here, never trusted as a precomputed value from outside
        debt_to_income = applicant.monthly_debt / applicant.monthly_income
        if debt_to_income > self.MAX_DEBT_TO_INCOME:
            return LoanDecision(False, f"debt to income ratio {debt_to_income:.2f} exceeds the maximum of {self.MAX_DEBT_TO_INCOME}")

        return LoanDecision(True, "meets the minimum credit score and debt to income requirements")


if __name__ == "__main__":
    # no controller, no HTTP request, no database connection anywhere in this file
    service = LoanApprovalService()

    alice = LoanApplicant("Alice", 720, 8000.0, 2000.0)
    bob = LoanApplicant("Bob", 580, 5000.0, 1000.0)

    alice_decision = service.evaluate(alice)
    print(f"{alice.name}: approved = {alice_decision.approved}, reason = {alice_decision.reason}")

    bob_decision = service.evaluate(bob)
    print(f"{bob.name}: approved = {bob_decision.approved}, reason = {bob_decision.reason}")

