#include <iostream>
#include <string>
using namespace std;

struct LoanApplicant {
    string name;
    int creditScore;
    double monthlyIncome;
    double monthlyDebt;
};

struct LoanDecision {
    bool approved;
    string reason;
};

class LoanApprovalService {
public:
    // the actual business rules, expressed as plain constants inside the service itself
    static const int MIN_CREDIT_SCORE = 650;
    static constexpr double MAX_DEBT_TO_INCOME = 0.40;

    // the one entry point into this layer, a plain object in, a plain object out
    LoanDecision evaluate(const LoanApplicant& applicant) {
        if (applicant.creditScore < MIN_CREDIT_SCORE) {
            return LoanDecision{ false, "credit score is below the minimum required" };
        }

        // derived data computed fresh here, never trusted as a precomputed value from outside
        double debtToIncome = applicant.monthlyDebt / applicant.monthlyIncome;
        if (debtToIncome > MAX_DEBT_TO_INCOME) {
            return LoanDecision{ false, "debt to income ratio exceeds the maximum allowed" };
        }

        return LoanDecision{ true, "meets the minimum credit score and debt to income requirements" };
    }
};

int main() {
    // no controller, no HTTP request, no database connection anywhere in this file
    LoanApprovalService service;

    LoanApplicant alice{ "Alice", 720, 8000.0, 2000.0 };
    LoanApplicant bob{ "Bob", 580, 5000.0, 1000.0 };

    LoanDecision aliceDecision = service.evaluate(alice);
    cout << alice.name << ": approved = " << boolalpha << aliceDecision.approved << ", reason = " << aliceDecision.reason << endl;

    LoanDecision bobDecision = service.evaluate(bob);
    cout << bob.name << ": approved = " << boolalpha << bobDecision.approved << ", reason = " << bobDecision.reason << endl;

    return 0;
}
